import useAxiosLarge from "../../hook/useAxiosLarge/useAxiosLarge";
import "./Hour.css";

const Hour = ({ city, temp }) => {
  const { dataL } = useAxiosLarge({ city: city });
  const kelvinToCelsius = (num) => {
    return num - 273.15;
  };
  const kelvinToFar = (num) => {
    return ((num - 273.15) * 9) / 5 + 32;
  };
  return (
    <div>
      <div className="eachTemp">
        <p>{dataL?.list[0].dt_txt}</p>
        {temp === "C" ? (
          <p>Math.trunc(kelvinToCelsius(dataL?.list[0].main.temp)) °C</p>
        ) : (
          <p>Math.trunc(kelvinToFar(dataL?.list[0].main.temp)) °F</p>
        )}

        <p>{dataL?.list[0].main.temp}</p>
        <p>{dataL?.list[0].weather[0].main}</p>
      </div>
      <div className="eachTemp"></div>
      <div className="eachTemp"></div>
      <div className="eachTemp"></div>
      <div className="eachTemp"></div>
      <div className="eachTemp"></div>
    </div>
  );
};

export default Hour;
